using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 演出同步模式
/// </summary>
public enum PerformanceSyncMode
{
    /// <summary>顺序执行模式：命令按列表从上到下依次执行，执行完即结束（默认，适合短演出）</summary>
    Sequential,

    /// <summary>BGM驱动模式：一整首歌作为演出时间轴，命令可在指定时间戳触发（适合长剧情演出）</summary>
    BGMDriven,
}

/// <summary>
/// 演出场景数据 —— 定义一幕剧情演出的完整编排。
/// 
/// 【什么是"一幕演出"】
/// 一出完整的意识流演出可以由多个 PerformanceSceneData 串联组成，
/// 每个 Scene 代表一个"情绪段落"或"意识片段"。
/// 例如："回忆闪回" → "内心独白" → "现实回归" 各为一个 Scene。
/// 
/// 【两种演出模式】
/// - Sequential（顺序模式）：命令从上到下逐条执行，执行完即结束。适合短小精悍的意识流片段。
/// - BGMDriven（BGM驱动模式）：以一首歌为时间轴，命令可以绑定到歌曲的特定秒数触发。
///   演出随歌曲开始而开始、随歌曲结束而结束。适合"一首歌 + 一整段剧情"的长演出。
/// 
/// 【与 StoryLineData 的关系】
/// StoryLineData 是纯文本对白序列，适用于传统对话剧情。
/// PerformanceSceneData 是更丰富的视听演出编排，适用于需要实时演算的意识流段落。
/// 两者可以共存——在关键剧情节点切换到演出模式，日常对话使用对白模式。
/// 
/// 【创建方式】
/// Project 窗口右键 → Create → 剧情演出 → 演出场景
/// </summary>
[CreateAssetMenu(fileName = "NewPerformanceScene", menuName = "剧情演出/演出场景", order = 0)]
public class PerformanceSceneData : ScriptableObject
{
    [Header("========== 场景信息 ==========")]

    [Tooltip("场景名称（用于编辑器识别）")]
    public string sceneName;

    [Tooltip("所属章节编号")]
    [Range(1, 20)]
    public int chapterId = 1;

    [Tooltip("所属模块编号（同章节下唯一）")]
    [Range(1, 50)]
    public int moduleId = 1;

    [Header("========== 演出同步模式 ==========")]

    [Tooltip("演出同步模式：\nSequential = 逐条执行命令（默认）\nBGMDriven = 以一首歌为时间轴驱动演出")]
    public PerformanceSyncMode syncMode = PerformanceSyncMode.Sequential;

    [Tooltip("演出主BGM资源名（BGMDriven模式专用，演出将以此曲的时长为总时长）")]
    public string performanceBGMResName;

    [Tooltip("演出主BGM所在AB包名（BGMDriven模式专用）")]
    public string performanceBGMABName;

    [Tooltip("演出主BGM音量（BGMDriven模式专用）")]
    [Range(0f, 1f)]
    public float performanceBGMVolume = 0.8f;

    [Tooltip("演出总时长（秒）。BGMDriven模式默认为0表示跟随BGM长度，手动设置可覆盖")]
    public float performanceDuration;

    [Header("========== 初始场景设置 ==========")]

    [Tooltip("初始背景Sprite资源名")]
    public string initialBackgroundName;

    [Tooltip("初始背景所在AB包名")]
    public string initialBackgroundABName;

    [Tooltip("初始背景音乐资源名（Sequential模式的背景音乐，BGMDriven模式请使用上面的主BGM）")]
    public string initialBGMResName;

    [Tooltip("初始背景音乐所在AB包名")]
    public string initialBGMABName;

    [Tooltip("初始BGM音量")]
    [Range(0f, 1f)]
    public float initialBGMVolume = 0.8f;

    [Header("========== 命令序列 ==========")]

    [Tooltip("命令序列，从上到下依次执行（Parallel命令内的子命令可并行）\nBGMDriven模式下，设置timestamp的命令将在指定时刻触发")]
    public List<PerformanceCommand> commands = new List<PerformanceCommand>();

    // ============================================================
    //  辅助属性
    // ============================================================

    /// <summary>命令总数</summary>
    public int CommandCount => commands?.Count ?? 0;

    /// <summary>获取指定索引的命令</summary>
    public PerformanceCommand GetCommand(int index)
    {
        if (commands == null || index < 0 || index >= commands.Count)
            return null;
        return commands[index];
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 演出命令 —— 剧情演出中的最小执行单元。
/// 
/// 【设计思路】
/// 所有命令共享同一数据结构，通过 type 字段区分具体行为。
/// 不同命令使用不同的参数字段，未使用的字段保持默认值即可。
/// 这样设计的优势是可以放在同一个 List 中序列化到 ScriptableObject。
/// 
/// 【意识流特有的命令设计】
/// - FloatingText：文字在屏幕随机位置浮现后消失，模拟意识碎片
/// - Flash：画面闪白/闪黑，表现心理冲击
/// - ScreenColorFilter：色调滤镜切换，烘托情绪氛围
/// - CameraShake/Zoom：镜头语言增强情感表达
/// </summary>
[Serializable]
public class PerformanceCommand
{
    [Tooltip("命令类型")]
    public EPerformanceCommandType type;

    // ============================================================
    //  通用参数
    // ============================================================

    [Tooltip("持续时间（秒），用于过渡/动画类命令")]
    public float duration;

    [Tooltip("延迟开始时间（秒），从上一命令结束后延迟N秒再执行")]
    public float delay;

    [Tooltip("触发时间戳（秒）。BGMDriven模式下，>0表示从演出开始后第N秒触发。设置此值的命令不受列表顺序约束")]
    public float timestamp;

    // ============================================================
    //  文字类参数
    // ============================================================

    [Tooltip("说话人名称（Dialogue命令使用）")]
    public string speakerName;

    [Tooltip("对话文本内容（Dialogue/FloatingText命令使用）")]
    [TextArea(3, 6)]
    public string textContent;

    [Tooltip("文字显示位置锚点（0=左 1=中 2=右）")]
    [Range(0, 2)]
    public int textAnchor;

    // ============================================================
    //  角色类参数
    // ============================================================

    [Tooltip("目标角色名称（对应场景中的角色GameObject名）")]
    public string characterName;

    [Tooltip("是否显示角色")]
    public bool characterVisible;

    [Tooltip("角色目标位置（屏幕坐标，0-1归一化）")]
    public Vector2 characterTargetPos;

    [Tooltip("角色新表情/姿态Sprite（资源名）")]
    public string characterSpriteName;

    [Tooltip("角色Sprite所在的AB包名")]
    public string characterSpriteABName;

    [Tooltip("角色震动强度")]
    public float shakeIntensity;

    // ============================================================
    //  场景/背景类参数
    // ============================================================

    [Tooltip("新背景Sprite资源名")]
    public string backgroundSpriteName;

    [Tooltip("背景Sprite所在的AB包名")]
    public string backgroundSpriteABName;

    [Tooltip("背景滚动方向")]
    public Vector2 backgroundScrollDir;

    [Tooltip("背景滚动速度")]
    public float backgroundScrollSpeed;

    // ============================================================
    //  镜头类参数
    // ============================================================

    [Tooltip("摄像机震动强度")]
    public float cameraShakeStrength;

    [Tooltip("摄像机震动频率")]
    public int cameraShakeVibrato;

    [Tooltip("摄像机目标缩放值（1=正常）")]
    public float cameraZoomTarget;

    [Tooltip("摄像机平移目标（世界坐标偏移）")]
    public Vector3 cameraPanOffset;

    [Tooltip("摄像机目标旋转角度（Z轴，表现眩晕/空间扭曲）")]
    public float cameraRotateAngle;

    // ============================================================
    //  特效类参数
    // ============================================================

    [Tooltip("颜色滤镜目标色")]
    public Color screenFilterColor;

    [Tooltip("淡入淡出目标Alpha（0=全透明 1=不透明）")]
    [Range(0f, 1f)]
    public float screenFadeAlpha;

    [Tooltip("模糊强度")]
    [Range(0f, 10f)]
    public float blurStrength;

    [Tooltip("粒子特效预制体资源名")]
    public string particleResName;

    [Tooltip("粒子特效所在AB包名")]
    public string particleABName;

    [Tooltip("粒子特效生成位置（世界坐标）")]
    public Vector3 particleSpawnPos;

    [Tooltip("闪白/闪黑颜色")]
    public Color flashColor;

    // ============================================================
    //  音频类参数
    // ============================================================

    [Tooltip("音频资源名")]
    public string audioResName;

    [Tooltip("音频所在AB包名")]
    public string audioABName;

    [Tooltip("音频音量")]
    [Range(0f, 1f)]
    public float audioVolume;

    // ============================================================
    //  并行组参数
    // ============================================================

    [Tooltip("并行执行的子命令列表（仅Parallel类型使用）")]
    public List<PerformanceCommand> parallelCommands;

    // ============================================================
    //  辅助方法
    // ============================================================

    /// <summary>
    /// 获取实际等待时间（含延迟）。
    /// Wait命令返回duration+delay，其他命令返回delay。
    /// </summary>
    public float GetTotalWaitTime()
    {
        float baseTime = type == EPerformanceCommandType.Wait ? duration : 0f;
        return baseTime + delay;
    }
}

