    [SerializeField] private GameObject bg_DeepSea;
    [Tooltip("暴风背景预制体(带闪电Shader)")]
    [SerializeField] private GameObject bg_Storm;
    [Tooltip("黎明背景预制体(带光晕Shader)")]
